// @vssaros/dsh-kb — 飞书剪存（Feishu Clip）轮询的纯逻辑（2026-11-11）
//
// 方案 A（用户选）：不做云文档创建事件订阅，改用**轮询 + 游标**驱动第 2~6 步：
//   wiki +node-list → 新节点 → docs +fetch 读正文 → 判定 Generated by Feishu Clip
//   → 写 数据源/raw → 总结 → 写 知识库列表/<库> → 同步回飞书。
//
// ⚠ 纯函数：不 import fs / child_process / 其它插件，便于守卫直测。
// ⚠ 真机约束：当前 lark-cli 1.0.98 的 `event consume` 不支持 drive/docs/wiki 域
//   （实测 `event schema drive.file.created_in_folder_v1` → unknown EventKey），
//   且账号 profile strict-mode=bot 时 `--as user` 会被拒 ⇒ identity 必须可配。

/** 剪存文档的正文标记（飞书官方浏览器扩展 Feishu Clip 生成）。 */
export const CLIP_MARKER = 'Generated by Feishu Clip';
/** 游标相对 vault 根的落点（只增不删，处理成功才推进）。 */
export const CLIP_CURSOR_REL = '.kb/clip-cursor.json';

export const CLIP_DEFAULTS = Object.freeze({
	enabled: false,
	scheduleMinutes: 10,
	spaceId: 'my_library',
	identity: 'user',
	targetKb: '',
	targetSpaceId: '',
	sessionId: '',
	limit: 5,
	marker: CLIP_MARKER,
});

/** 列节点的 CLI 参数（照 SPACE_LIST_ARGS 的形态；`--profile` 由 runLarkCli 自动前置）。 */
export function nodeListArgs(spaceId, identity) {
	const id = String(spaceId ?? '').trim() || 'my_library';
	const args = ['wiki', '+node-list', '--space-id', id, '--page-all', '--format', 'json'];
	if (String(identity ?? '').trim() === 'user') { args.push('--as', 'user'); }
	return args;
}

/** 读单篇正文的 CLI 参数（与 feishuDocs.buildDocReadArgs 同形）。 */
export function clipDocArgs(objToken) {
	return ['docs', '+fetch', '--doc', String(objToken ?? '').trim(),
		'--doc-format', 'markdown', '--detail', 'with-ids'];
}

/** 抠出文本里的第一个 JSON 值（CLI 可能混日志行 / 升级通知）。 */
function looseJson(text) {
	const s = String(text ?? '');
	for (const [open, close] of [['{', '}'], ['[', ']']]) {
		const start = s.indexOf(open);
		if (start < 0) { continue; }
		let depth = 0;
		for (let i = start; i < s.length; i++) {
			if (s[i] === open) { depth++; }
			else if (s[i] === close) {
				depth--;
				if (depth === 0) {
					try { return JSON.parse(s.slice(start, i + 1)); } catch { return undefined; }
				}
			}
		}
	}
	return undefined;
}

/**
 * 解析 `wiki +node-list` ⇒ `[{ id, objToken, nodeToken, title, objType, createTime }]`。
 * 递归找（不同 CLI 版本可能包在 `data.items` / `data.nodes` / 裸数组里），按 token 去重。
 */
export function parseNodeList(raw, extra = '') {
	const root = looseJson(String(raw ?? '') + '\n' + String(extra ?? ''));
	const out = [];
	const seen = new Set();
	const walk = (node, depth) => {
		if (!node || typeof node !== 'object' || depth > 8) { return; }
		if (Array.isArray(node)) { for (const x of node) { walk(x, depth + 1); } return; }
		const objToken = String(node.obj_token ?? node.objToken ?? '');
		const nodeToken = String(node.node_token ?? node.nodeToken ?? '');
		const id = objToken || nodeToken;
		if (id && !seen.has(id)) {
			seen.add(id);
			out.push({
				id,
				objToken, nodeToken,
				title: String(node.title ?? node.name ?? ''),
				objType: String(node.obj_type ?? node.objType ?? ''),
				createTime: String(node.obj_create_time ?? node.objCreateTime
					?? node.node_create_time ?? node.nodeCreateTime ?? ''),
			});
		}
		for (const v of Object.values(node)) { walk(v, depth + 1); }
	};
	walk(root, 0);
	return out;
}

/** 正文是否来自飞书剪存（大小写不敏感；marker 可配，便于换语言/换扩展）。 */
export function isClipDoc(markdown, marker = CLIP_MARKER) {
	const text = String(markdown ?? '').toLowerCase();
	const needle = String(marker ?? CLIP_MARKER).toLowerCase();
	return !!needle && text.includes(needle);
}

/** 目录段净化：拒 `..` / 空段 / 绝对路径，并可剥掉 `知识库列表/` 前缀。 */
export function sanitizeSegment(raw) {
	let v = String(raw ?? '').trim().replace(/\\/g, '/').replace(/^\/+|\/+$/g, '');
	if (v.startsWith('知识库列表/')) { v = v.slice('知识库列表/'.length); }
	const parts = v.split('/').filter(Boolean);
	if (!parts.length || parts.some(p => p === '.' || p === '..')) { return ''; }
	return parts.join('/');
}

/** 合并配置（并做边界钳制），坏值一律回默认，不抛。 */
export function clipConfigOf(raw) {
	const r = raw && typeof raw === 'object' ? raw : {};
	const num = (v, d, lo, hi) => {
		const n = Number(v);
		return Number.isFinite(n) ? Math.max(lo, Math.min(hi, Math.floor(n))) : d;
	};
	return {
		...CLIP_DEFAULTS,
		...r,
		enabled: r.enabled === true,
		scheduleMinutes: num(r.scheduleMinutes, CLIP_DEFAULTS.scheduleMinutes, 1, 1440),
		limit: num(r.limit, CLIP_DEFAULTS.limit, 1, 50),
		spaceId: String(r.spaceId || CLIP_DEFAULTS.spaceId).trim(),
		identity: r.identity === 'bot' ? 'bot' : 'user',
		targetKb: sanitizeSegment(r.targetKb),
		targetSpaceId: String(r.targetSpaceId ?? '').trim(),
		sessionId: String(r.sessionId ?? '').trim(),
		marker: String(r.marker || CLIP_MARKER),
	};
}

/** 文件名 slug（照 web-content-import/SKILL.md:215：去非法字符、空白折 `-`、≤60、同名加后缀）。 */
export function slugOf(title, id) {
	const base = String(title ?? '').trim()
		.replace(/[\\/:*?"<>|#%{}]/g, '')
		.replace(/\s+/g, '-')
		.replace(/-+/g, '-')
		.replace(/^-+|-+$/g, '')
		.slice(0, 60);
	return base || ('clip-' + String(id ?? '').replace(/[^A-Za-z0-9]/g, '').slice(0, 12).toLowerCase());
}

/** raw 素材正文（**不写 YAML frontmatter**，照 SKILL.md:216-217 的素材层契约）。 */
export function rawMarkdownOf({ title, markdown, url, at }) {
	const head = `# ${String(title || '未命名剪存').trim()}\n\n`;
	const meta = `> 来源：Feishu Clip${url ? ' · ' + String(url) : ''}\n> 采集时间：${String(at ?? '')}\n\n`;
	return head + meta + String(markdown ?? '').trim() + '\n';
}

const yamlSafe = (s) => String(s ?? '').replace(/["\r\n:]/g, ' ').trim();

/** 笔记层：总结服务返回纯正文时，由 Host 补最小 frontmatter（已带 frontmatter 就原样保留）。 */
export function noteMarkdownOf({ title, body, sourceRel, at }) {
	const b = String(body ?? '').trim();
	if (!b) { return ''; }
	if (b.startsWith('---')) { return b + '\n'; }
	const fm = [
		'---',
		`title: ${yamlSafe(title)}`,
		'type: concept',
		`sources: ["${yamlSafe(sourceRel)}"]`,
		`created: ${String(at ?? '').slice(0, 10)}`,
		'tags: [剪存]',
		'---',
		'',
	].join('\n');
	return fm + '\n' + b + '\n';
}

/** 游标：坏 JSON 不抛（照 parseRootConfig 的口径）。 */
export function parseCursor(raw) {
	try {
		const obj = JSON.parse(String(raw ?? ''));
		const seen = obj && typeof obj.seen === 'object' && obj.seen && !Array.isArray(obj.seen) ? obj.seen : {};
		return { version: 1, seen, lastRun: String(obj?.lastRun ?? '') };
	} catch { return { version: 1, seen: {}, lastRun: '' }; }
}

export function serializeCursor(cur) {
	return JSON.stringify({
		version: 1,
		seen: (cur && cur.seen) || {},
		lastRun: String(cur?.lastRun ?? ''),
	}, null, 2);
}
